// Vendored Pokémon Showdown Champions mod data, generated by
// scripts/build-champions-data.ts from smogon/pokemon-showdown at the SHA
// pinned there (provenance in meta.json). Regenerate with
// `pnpm build:champions-data`.
//
// Only the five tables @pkmn/dex's Dex.mod actually reads are vendored.
// The upstream mod's other files (conditions/formats/rulesets/scripts) are
// sim-only: the dex loader ignores them apart from Scripts.inherit — absent
// in the Champions mod, so the mod parents on gen9 with or without it — and
// backfills the omitted tables wholesale from gen9. Function-valued fields
// (battle callbacks) were dropped at generation time; the dex layer never
// invokes them. `inherit: true` markers and `null` deletion sentinels are
// preserved — Dex.mod's merge semantics depend on both.

import type { ModData } from '@pkmn/dex'

import Abilities from './abilities.json'
import FormatsData from './formats-data.json'
import Items from './items.json'
import Learnsets from './learnsets.json'
import Moves from './moves.json'

// The JSON literal types don't line up with ModData's callback-bearing table
// types (the callbacks are exactly what generation strips), so the cast goes
// through unknown — same trust boundary the previous `@pkmn/mods/champions`
// import crossed via its `unknown`-typed shim.
export const championsModData: ModData = {
  Abilities,
  FormatsData,
  Items,
  Learnsets,
  Moves,
} as unknown as ModData
